CREATE OR REPLACE FUNCTION private.protect_creative_asset_storage_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.storage_bucket is distinct from old.storage_bucket
     or new.storage_path is distinct from old.storage_path then
    raise exception 'creative asset storage identity is immutable'
      using errcode = '23514';
  end if;

  if new.user_id is distinct from old.user_id
     or new.campaign_id is distinct from old.campaign_id then
    raise exception 'creative asset owner and campaign identity is immutable'
      using errcode = '23514';
  end if;

  if (
    old.storage_bucket is not null
    or old.storage_path is not null
    or old.provider_name = 'manual_upload'
    or new.provider_name = 'manual_upload'
  ) and new.provider_name is distinct from old.provider_name then
    raise exception 'manual creative provider identity is immutable'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ack_billing_access_key_reveal_delivery(p_checkout_session_id text, p_delivery_token_hash text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  access_key public.billing_access_keys%rowtype;
  acknowledged_at timestamptz := timezone('utc', now());
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role is required to acknowledge an access-key reveal delivery';
  end if;
  if nullif(trim(coalesce(p_checkout_session_id, '')), '') is null
    or coalesce(p_delivery_token_hash, '') !~ '^[0-9a-f]{64}$' then
    return 'rejected';
  end if;

  select * into access_key
  from public.billing_access_keys candidate
  where candidate.stripe_checkout_session_id = trim(p_checkout_session_id)
  for update;

  if access_key.id is null then
    return 'rejected';
  end if;
  if access_key.reveal_consumed_at is not null
    and access_key.reveal_ack_token_hash = p_delivery_token_hash then
    return 'already_acknowledged';
  end if;
  if access_key.reveal_consumed_at is not null
    or access_key.reveal_delivery_token_hash is distinct from p_delivery_token_hash then
    return 'rejected';
  end if;

  update public.billing_access_keys candidate
  set reveal_consumed_at = acknowledged_at,
      reveal_verifier_hash = null,
      reveal_verifier_expires_at = null,
      reveal_delivery_token_hash = null,
      reveal_delivery_started_at = null,
      reveal_delivery_expires_at = null,
      reveal_ack_token_hash = p_delivery_token_hash,
      metadata = (candidate.metadata - 'reveal_ciphertext') || jsonb_build_object(
        'revealed_at', acknowledged_at,
        'reveal_delivery_acknowledged', true
      ),
      updated_at = acknowledged_at
  where candidate.id = access_key.id
    and candidate.reveal_consumed_at is null
    and candidate.reveal_delivery_token_hash = p_delivery_token_hash;

  return case when found then 'acknowledged' else 'rejected' end;
end;
$function$

CREATE OR REPLACE FUNCTION public.arm_campaign_launch_provider_mutation(p_launch_id uuid, p_worker_id text, p_lease_token uuid, p_lease_generation bigint, p_stage text, p_object_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  launch public.campaign_launch_records%rowtype;
  pending_mutation jsonb;
  armed_at timestamptz := timezone('utc', now());
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role is required to arm provider mutations';
  end if;

  if p_stage not in ('campaign', 'adset', 'creative', 'ad')
    or nullif(trim(coalesce(p_object_key, '')), '') is null
    or length(trim(p_object_key)) > 500 then
    raise exception 'campaign launch provider mutation identity is invalid';
  end if;

  select * into launch
  from public.campaign_launch_records candidate
  where candidate.id = p_launch_id
  for update;

  if launch.id is null
    or launch.result_status <> 'processing'
    or launch.schedule_locked_by is distinct from p_worker_id
    or launch.schedule_lease_token is distinct from p_lease_token
    or launch.schedule_lease_generation is distinct from p_lease_generation
    or launch.schedule_locked_until <= armed_at
    or launch.launch_input_snapshot is null
    or launch.launch_input_digest is null then
    return false;
  end if;

  pending_mutation := launch.execution_metadata -> 'providerMutationPending';
  if coalesce(pending_mutation ->> 'state', '') = 'pending' then
    return false;
  end if;

  update public.campaign_launch_records candidate
  set execution_metadata = candidate.execution_metadata || jsonb_build_object(
        'providerMutationPending', jsonb_build_object(
          'state', 'pending',
          'stage', p_stage,
          'objectKey', trim(p_object_key),
          'leaseGeneration', p_lease_generation,
          'armedAt', armed_at
        ),
        'providerMutationOutcome', 'ambiguous_until_receipted_or_explicitly_rejected'
      ),
      updated_at = armed_at
  where candidate.id = launch.id
    and candidate.result_status = 'processing'
    and candidate.schedule_locked_by = p_worker_id
    and candidate.schedule_lease_token = p_lease_token
    and candidate.schedule_lease_generation = p_lease_generation
    and candidate.schedule_locked_until > armed_at
    and coalesce(candidate.execution_metadata -> 'providerMutationPending' ->> 'state', '') <> 'pending';

  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.bind_credit_top_up_checkout_v1(p_intent_id uuid, p_organization_id uuid, p_user_id uuid, p_stripe_checkout_session_id text)
 RETURNS SETOF credit_top_up_intents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  intent public.credit_top_up_intents%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception using errcode = '42501', message = 'credit_top_up_service_role_required';
  end if;

  select * into strict intent
  from public.credit_top_up_intents existing
  where existing.id = p_intent_id
  for update;

  if intent.organization_id is distinct from p_organization_id
    or intent.user_id is distinct from p_user_id
    or nullif(trim(coalesce(p_stripe_checkout_session_id, '')), '') is null then
    raise exception using errcode = '42501', message = 'credit_top_up_checkout_identity_mismatch';
  end if;

  if intent.stripe_checkout_session_id is not null
    and intent.stripe_checkout_session_id is distinct from trim(p_stripe_checkout_session_id) then
    raise exception using errcode = '23505', message = 'credit_top_up_checkout_already_bound';
  end if;

  if intent.status = 'created' then
    update public.credit_top_up_intents existing
    set stripe_checkout_session_id = trim(p_stripe_checkout_session_id),
        status = 'checkout_created',
        checkout_bound_at = timezone('utc', now()),
        updated_at = timezone('utc', now())
    where existing.id = p_intent_id
    returning * into intent;
  end if;

  return next intent;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_billing_access_key_reconciliation(p_claim_token_hash text, p_user_id uuid, p_organization_id uuid, p_email text, p_lease_ms integer DEFAULT 600000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  access_key public.billing_access_keys%rowtype;
  changed_at timestamptz := timezone('utc', now());
  locked_until timestamptz;
  recovery_count integer := 0;
  recovered_without_token boolean := false;
  recovered_claim boolean := false;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role is required to claim access-key reconciliation';
  end if;

  if coalesce(p_claim_token_hash, '') !~ '^[0-9a-f]{64}$'
    or p_user_id is null
    or p_organization_id is null
    or nullif(trim(coalesce(p_email, '')), '') is null
    or length(trim(p_email)) > 320 then
    return jsonb_build_object('outcome', 'invalid');
  end if;

  if not exists (
      select 1
      from public.organizations organization
      where organization.id = p_organization_id
        and organization.owner_user_id = p_user_id
    )
    or not exists (
      select 1
      from public.organization_memberships membership
      where membership.organization_id = p_organization_id
        and membership.user_id = p_user_id
    ) then
    return jsonb_build_object('outcome', 'workspace_identity_mismatch');
  end if;

  select * into access_key
  from public.billing_access_keys candidate
  where candidate.claim_token_hash = p_claim_token_hash
  for update;

  if access_key.id is null then
    select count(*) into recovery_count
    from public.billing_access_keys candidate
    where candidate.status = 'claimed'
      and candidate.claimed_by_user_id = p_user_id
      and candidate.claimed_organization_id = p_organization_id
      and candidate.claim_reconciliation_status <> 'completed';

    if recovery_count > 1 then
      return jsonb_build_object('outcome', 'ambiguous_recovery');
    end if;

    if recovery_count = 1 then
      select * into access_key
      from public.billing_access_keys candidate
      where candidate.status = 'claimed'
        and candidate.claimed_by_user_id = p_user_id
        and candidate.claimed_organization_id = p_organization_id
        and candidate.claim_reconciliation_status <> 'completed'
      for update;
      recovered_without_token := true;
    end if;
  end if;

  if access_key.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  if access_key.status = 'preclaimed' then
    if access_key.expires_at is null or access_key.expires_at <= changed_at then
      return jsonb_build_object('outcome', 'expired', 'access_key_id', access_key.id);
    end if;
    if access_key.claim_token_expires_at is null or access_key.claim_token_expires_at <= changed_at then
      return jsonb_build_object('outcome', 'claim_token_expired', 'access_key_id', access_key.id);
    end if;
    if access_key.preclaimed_email is null
      or access_key.preclaimed_email is distinct from lower(trim(p_email)) then
      return jsonb_build_object('outcome', 'email_mismatch', 'access_key_id', access_key.id);
    end if;
  elsif access_key.status = 'claimed' then
    recovered_claim := true;
    if access_key.claimed_by_user_id is distinct from p_user_id
      or access_key.claimed_organization_id is distinct from p_organization_id
      or access_key.preclaimed_email is null
      or access_key.preclaimed_email is distinct from lower(trim(p_email)) then
      return jsonb_build_object('outcome', 'claim_identity_mismatch', 'access_key_id', access_key.id);
    end if;
    if access_key.claim_reconciliation_status = 'completed' then
      return jsonb_build_object('outcome', 'completed', 'access_key_id', access_key.id);
    end if;
  else
    return jsonb_build_object('outcome', 'invalid_status', 'access_key_id', access_key.id);
  end if;

  if access_key.claim_reconciliation_status = 'processing'
    and access_key.claim_reconciliation_locked_until > changed_at then
    return jsonb_build_object('outcome', 'in_progress', 'access_key_id', access_key.id);
  end if;

  locked_until := changed_at
    + make_interval(secs => least(greatest(coalesce(p_lease_ms, 600000), 60000), 1800000) / 1000.0);

  update public.billing_access_keys candidate
  set status = 'claimed',
      claimed_by_user_id = p_user_id,
      claimed_organization_id = p_organization_id,
      claimed_at = coalesce(candidate.claimed_at, changed_at),
      claim_reconciliation_status = 'processing',
      claim_reconciliation_lease_token = gen_random_uuid(),
      claim_reconciliation_locked_until = locked_until,
      claim_reconciliation_generation = candidate.claim_reconciliation_generation + 1,
      claim_reconciliation_last_error_code = null,
      metadata = candidate.metadata || jsonb_build_object(
        'claimed_source', case
          when recovered_without_token then 'app_context_recovery'
          else 'app_context_bootstrap'
        end,
        'provider_sync_status', 'pending',
        'claim_reconciliation_recoverable', true
      ),
      updated_at = changed_at
  where candidate.id = access_key.id
    and (
      candidate.status = 'preclaimed'
      or (
        candidate.status = 'claimed'
        and candidate.claimed_by_user_id = p_user_id
        and candidate.claimed_organization_id = p_organization_id
        and candidate.claim_reconciliation_status <> 'completed'
        and (
          candidate.claim_reconciliation_status <> 'processing'
          or candidate.claim_reconciliation_locked_until <= changed_at
        )
      )
    )
  returning * into access_key;

  if access_key.id is null then
    return jsonb_build_object('outcome', 'in_progress');
  end if;

  return jsonb_build_object(
    'outcome', case
      when recovered_without_token or recovered_claim then 'recovered'
      else 'acquired'
    end,
    'access_key', to_jsonb(access_key)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_inbound_sms_receipt(p_provider_message_id text, p_organization_id uuid, p_lead_id uuid, p_message_digest text, p_worker_id text, p_lease_ms integer DEFAULT 120000)
 RETURNS SETOF inbound_sms_receipts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  receipt public.inbound_sms_receipts%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role is required to claim inbound SMS receipts';
  end if;

  if nullif(trim(coalesce(p_provider_message_id, '')), '') is null
    or nullif(trim(coalesce(p_worker_id, '')), '') is null
    or trim(coalesce(p_message_digest, '')) !~ '^[0-9a-f]{64}$' then
    raise exception 'inbound SMS receipt identity is incomplete';
  end if;

  insert into public.inbound_sms_receipts (
    provider_message_id,
    organization_id,
    lead_id,
    message_digest,
    status,
    attempt_count
  ) values (
    trim(p_provider_message_id),
    p_organization_id,
    p_lead_id,
    trim(p_message_digest),
    'retrying',
    0
  )
  on conflict (provider_message_id) do nothing;

  select * into strict receipt
  from public.inbound_sms_receipts existing
  where existing.provider_message_id = trim(p_provider_message_id)
  for update;

  if receipt.organization_id <> p_organization_id
    or receipt.lead_id <> p_lead_id
    or receipt.message_digest <> trim(p_message_digest) then
    if receipt.status = 'processing'
      and receipt.locked_until > timezone('utc', now()) then
      -- Fail the colliding caller closed without invalidating the legitimate
      -- in-flight lease after it may already have applied an atomic effect.
      receipt.status := 'operator_action_required';
      receipt.locked_by := null;
      receipt.locked_until := null;
      receipt.lease_token := null;
      receipt.last_error_code := 'inbound_sms_identity_collision';
      return next receipt;
      return;
    end if;

    update public.inbound_sms_receipts existing
    set status = 'operator_action_required',
        locked_by = null,
        locked_until = null,
        lease_token = null,
        last_error_code = 'inbound_sms_identity_collision',
        updated_at = timezone('utc', now())
    where existing.provider_message_id = receipt.provider_message_id
    returning * into receipt;
    return next receipt;
    return;
  end if;

  if receipt.status = 'completed' or receipt.status = 'operator_action_required' then
    return next receipt;
    return;
  end if;

  if receipt.status = 'processing' and receipt.locked_until > timezone('utc', now()) then
    return next receipt;
    return;
  end if;

  if receipt.attempt_count >= 5 then
    update public.inbound_sms_receipts existing
    set status = 'operator_action_required',
        locked_by = null,
        locked_until = null,
        lease_token = null,
        last_error_code = 'inbound_sms_attempts_exhausted',
        updated_at = timezone('utc', now())
    where existing.provider_message_id = receipt.provider_message_id
    returning * into receipt;
    return next receipt;
    return;
  end if;

  update public.inbound_sms_receipts existing
  set status = 'processing',
      attempt_count = existing.attempt_count + 1,
      locked_by = trim(p_worker_id),
      locked_until = timezone('utc', now())
        + make_interval(secs => least(greatest(coalesce(p_lease_ms, 120000), 30000), 600000) / 1000.0),
      lease_token = gen_random_uuid(),
      lease_generation = existing.lease_generation + 1,
      last_error_code = null,
      updated_at = timezone('utc', now())
  where existing.provider_message_id = receipt.provider_message_id
  returning * into receipt;

  return next receipt;
end;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_expired_rate_limit_buckets(p_older_than interval DEFAULT '24:00:00'::interval)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  deleted_count integer;
begin
  delete from public.rate_limit_buckets
  where reset_at < timezone('utc', now()) - p_older_than;

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_credit_top_up_intent_v1(p_intent_id uuid, p_stripe_checkout_session_id text, p_stripe_customer_id text, p_stripe_payment_intent_id text, p_stripe_event_id text, p_amount_total integer, p_currency text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(organization_id uuid, user_id uuid, amount_cents integer, balance integer, ledger_id uuid, reused_existing boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  intent public.credit_top_up_intents%rowtype;
  credit_balance integer;
  credit_ledger_id uuid;
  credit_reused boolean;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception using errcode = '42501', message = 'credit_top_up_service_role_required';
  end if;

  select * into strict intent
  from public.credit_top_up_intents existing
  where existing.id = p_intent_id
  for update;

  if intent.stripe_checkout_session_id is distinct from trim(coalesce(p_stripe_checkout_session_id, ''))
    or intent.stripe_customer_id is distinct from trim(coalesce(p_stripe_customer_id, ''))
    or intent.amount_cents is distinct from p_amount_total
    or intent.currency is distinct from lower(trim(coalesce(p_currency, '')))
    or (
      intent.stripe_payment_intent_id is not null
      and intent.stripe_payment_intent_id is distinct from nullif(trim(coalesce(p_stripe_payment_intent_id, '')), '')
    )
    or nullif(trim(coalesce(p_stripe_event_id, '')), '') is null then
    raise exception using errcode = '22023', message = 'credit_top_up_authoritative_payment_mismatch';
  end if;

  if intent.status = 'created' then
    raise exception using errcode = '55000', message = 'credit_top_up_checkout_not_bound';
  end if;

  if intent.status = 'operator_action_required' then
    raise exception using errcode = '55000', message = 'credit_top_up_operator_action_required';
  end if;

  select grant_result.balance, grant_result.ledger_id, grant_result.reused_existing
  into credit_balance, credit_ledger_id, credit_reused
  from public.grant_user_credits(
    intent.user_id,
    intent.organization_id,
    intent.amount_cents,
    'stripe_credit_top_up',
    'stripe_checkout_session',
    intent.stripe_checkout_session_id,
    'stripe_credit_top_up:' || intent.id::text,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'creditTopUpIntentId', intent.id,
      'stripeEventId', trim(p_stripe_event_id),
      'stripePaymentIntentId', nullif(trim(coalesce(p_stripe_payment_intent_id, '')), '')
    )
  ) grant_result;

  if credit_ledger_id is null then
    raise exception using errcode = 'P0001', message = 'credit_top_up_ledger_missing';
  end if;

  if intent.status <> 'completed' then
    update public.credit_top_up_intents existing
    set status = 'completed',
        stripe_payment_intent_id = nullif(trim(coalesce(p_stripe_payment_intent_id, '')), ''),
        source_event_id = trim(p_stripe_event_id),
        completed_at = timezone('utc', now()),
        updated_at = timezone('utc', now())
    where existing.id = intent.id;
  elsif intent.source_event_id is distinct from trim(p_stripe_event_id) then
    -- A different Stripe event may replay the same completed Checkout Session;
    -- the credit ledger idempotency key remains the durable duplicate fence.
    credit_reused := true;
  end if;

  return query select
    intent.organization_id,
    intent.user_id,
    intent.amount_cents,
    credit_balance,
    credit_ledger_id,
    credit_reused;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_inbound_sms_compliance_receipt(p_provider_message_id text, p_worker_id text, p_lease_token uuid, p_lease_generation bigint, p_action text)
 RETURNS SETOF inbound_sms_receipts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  receipt public.inbound_sms_receipts%rowtype;
  lead_record public.leads%rowtype;
  completed_result jsonb;
  captured_at timestamptz := timezone('utc', now());
  response_text text;
  result_status text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role is required to complete inbound SMS compliance receipts';
  end if;

  if nullif(trim(coalesce(p_provider_message_id, '')), '') is null
    or nullif(trim(coalesce(p_worker_id, '')), '') is null
    or p_lease_token is null
    or p_lease_generation is null
    or p_lease_generation < 1 then
    raise exception 'inbound SMS compliance lease identity is incomplete';
  end if;

  if p_action is null or p_action not in ('opt_out', 'opt_in', 'help') then
    raise exception 'inbound SMS compliance action is invalid';
  end if;

  select * into receipt
  from public.inbound_sms_receipts existing
  where existing.provider_message_id = trim(p_provider_message_id)
  for update;

  if receipt.provider_message_id is null
    or receipt.status <> 'processing'
    or receipt.locked_by is distinct from trim(p_worker_id)
    or receipt.lease_token is distinct from p_lease_token
    or receipt.lease_generation is distinct from p_lease_generation
    or receipt.locked_until is null
    or receipt.locked_until <= timezone('utc', now()) then
    return;
  end if;

  select * into lead_record
  from public.leads existing
  where existing.id = receipt.lead_id
    and existing.organization_id = receipt.organization_id
  for update;

  if lead_record.id is null then
    raise exception 'inbound SMS compliance lead identity is missing';
  end if;

  if p_action = 'opt_out' then
    update public.leads existing
    set sms_opted_out_at = coalesce(existing.sms_opted_out_at, captured_at),
        status = 'lost',
        metadata = case
          when jsonb_typeof(existing.metadata) = 'object' then existing.metadata
          else '{}'::jsonb
        end || jsonb_build_object(
          'sms_opt_out',
          jsonb_build_object(
            'status', 'opted_out',
            'opted_out_at', coalesce(existing.sms_opted_out_at, captured_at)
          )
        )
    where existing.id = receipt.lead_id
      and existing.organization_id = receipt.organization_id;

    response_text := 'You have been unsubscribed and will not receive more messages.';
    result_status := 'lost';
  elsif p_action = 'opt_in' then
    update public.leads existing
    set sms_opted_out_at = null,
        metadata = case
          when jsonb_typeof(existing.metadata) = 'object' then existing.metadata
          else '{}'::jsonb
        end || jsonb_build_object(
          'sms_opt_in',
          jsonb_build_object(
            'status', 'opted_in',
            'opted_in_at', captured_at,
            'source', 'inbound_start'
          )
        ),
        consent_metadata = jsonb_build_object(
          'source', 'inbound_start',
          'captured_at', captured_at,
          'sms', jsonb_build_object(
            'consented', true,
            'captured_at', captured_at,
            'phone', existing.phone,
            'consent_copy', 'Reply START to resume SMS messages. Message and data rates may apply. Reply STOP to opt out or HELP for help.',
            'opt_out_copy', 'Reply STOP to opt out or HELP for help.',
            'source_url', null,
            'privacy_url', '/privacy',
            'terms_url', '/terms'
          )
        )
    where existing.id = receipt.lead_id
      and existing.organization_id = receipt.organization_id;

    response_text := 'You are subscribed again. Reply STOP to opt out or HELP for help. Message and data rates may apply.';
    result_status := coalesce(lead_record.status::text, 'new');
  else
    response_text := 'DealFlow OS lead updates: reply STOP to opt out, START to resume, or contact the business directly for help. Message and data rates may apply.';
    result_status := coalesce(lead_record.status::text, 'new');
  end if;

  completed_result := jsonb_build_object(
    'leadId', receipt.lead_id::text,
    'response', response_text,
    'status', result_status,
    'slots', '[]'::jsonb,
    'blocked', false,
    'complianceAction', p_action
  );

  update public.inbound_sms_receipts existing
  set status = 'completed',
      result = completed_result,
      last_error_code = null,
      locked_by = null,
      locked_until = null,
      lease_token = null,
      completed_at = captured_at,
      updated_at = captured_at
  where existing.provider_message_id = receipt.provider_message_id
    and existing.status = 'processing'
    and existing.locked_by = trim(p_worker_id)
    and existing.lease_token = p_lease_token
    and existing.lease_generation = p_lease_generation
  returning * into receipt;

  if receipt.status = 'completed' then
    return next receipt;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_rate_limit_bucket(p_bucket_key text, p_max_requests integer, p_window_ms integer)
 RETURNS TABLE(allowed boolean, remaining integer, reset_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  bucket public.rate_limit_buckets%rowtype;
  now_at timestamptz := now();
  next_reset timestamptz := now() + (greatest(p_window_ms, 1000)::text || ' milliseconds')::interval;
begin
  if p_bucket_key is null or length(trim(p_bucket_key)) = 0 then
    raise exception 'bucket_key is required';
  end if;

  if p_max_requests <= 0 then
    raise exception 'max_requests must be positive';
  end if;

  insert into public.rate_limit_buckets (bucket_key, request_count, reset_at)
  values (p_bucket_key, 0, next_reset)
  on conflict (bucket_key) do nothing;

  select *
  into bucket
  from public.rate_limit_buckets
  where rate_limit_buckets.bucket_key = p_bucket_key
  for update;

  if bucket.reset_at <= now_at then
    update public.rate_limit_buckets
    set request_count = 1,
        reset_at = next_reset,
        updated_at = now_at
    where rate_limit_buckets.bucket_key = p_bucket_key;

    allowed := true;
    remaining := greatest(p_max_requests - 1, 0);
    reset_at := next_reset;
    return next;
    return;
  end if;

  if bucket.request_count >= p_max_requests then
    allowed := false;
    remaining := 0;
    reset_at := bucket.reset_at;
    return next;
    return;
  end if;

  update public.rate_limit_buckets
  set request_count = bucket.request_count + 1,
      updated_at = now_at
  where rate_limit_buckets.bucket_key = p_bucket_key;

  allowed := true;
  remaining := greatest(p_max_requests - bucket.request_count - 1, 0);
  reset_at := bucket.reset_at;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_user_credits(p_user_id uuid, p_organization_id uuid, p_amount integer, p_reason text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(allowed boolean, balance integer, ledger_id uuid, reused_existing boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  balance_record public.organization_user_credits%rowtype;
  existing_ledger public.user_credit_ledger%rowtype;
  inserted_ledger public.user_credit_ledger%rowtype;
  normalized_reason text := nullif(trim(coalesce(p_reason, '')), '');
  normalized_reference_type text := nullif(trim(coalesce(p_reference_type, '')), '');
  normalized_reference_id text := nullif(trim(coalesce(p_reference_id, '')), '');
  normalized_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  next_balance integer;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception using errcode = '42501', message = 'credit_service_role_required';
  end if;

  if p_user_id is null or p_organization_id is null
    or p_amount is null or p_amount <= 0
    or normalized_reason is null then
    raise exception using errcode = '22023', message = 'credit_consume_identity_invalid';
  end if;

  if not exists (
    select 1 from public.organizations organization_record
    where organization_record.id = p_organization_id
      and organization_record.owner_user_id = p_user_id
  ) and not exists (
    select 1 from public.organization_memberships membership_record
    where membership_record.organization_id = p_organization_id
      and membership_record.user_id = p_user_id
  ) then
    raise exception using errcode = '42501', message = 'credit_actor_not_workspace_member';
  end if;

  insert into public.organization_user_credits (organization_id, user_id, balance)
  values (p_organization_id, p_user_id, 0)
  on conflict (organization_id, user_id) do nothing;

  select * into strict balance_record
  from public.organization_user_credits credit_record
  where credit_record.organization_id = p_organization_id
    and credit_record.user_id = p_user_id
  for update;

  if normalized_idempotency_key is not null then
    select * into existing_ledger
    from public.user_credit_ledger ledger_record
    where ledger_record.organization_id = p_organization_id
      and ledger_record.user_id = p_user_id
      and ledger_record.idempotency_key = normalized_idempotency_key
    limit 1;

    if existing_ledger.id is not null then
      if existing_ledger.delta is distinct from -p_amount
        or existing_ledger.reason is distinct from normalized_reason
        or existing_ledger.reference_type is distinct from normalized_reference_type
        or existing_ledger.reference_id is distinct from normalized_reference_id then
        raise exception using errcode = '23505', message = 'credit_idempotency_identity_collision';
      end if;

      return query select true, existing_ledger.balance_after, existing_ledger.id, true;
      return;
    end if;
  end if;

  if balance_record.balance < p_amount then
    return query select false, balance_record.balance, null::uuid, false;
    return;
  end if;

  next_balance := balance_record.balance - p_amount;

  update public.organization_user_credits credit_record
  set balance = next_balance,
      updated_at = timezone('utc', now())
  where credit_record.organization_id = p_organization_id
    and credit_record.user_id = p_user_id;

  insert into public.user_credit_ledger (
    user_id,
    organization_id,
    delta,
    balance_after,
    reason,
    reference_type,
    reference_id,
    idempotency_key,
    metadata
  ) values (
    p_user_id,
    p_organization_id,
    -p_amount,
    next_balance,
    normalized_reason,
    normalized_reference_type,
    normalized_reference_id,
    normalized_idempotency_key,
    coalesce(p_metadata, '{}'::jsonb)
  ) returning * into inserted_ledger;

  return query select true, next_balance, inserted_ledger.id, false;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_campaign_plan_with_entitlement_v1(p_campaign_id uuid, p_organization_id uuid, p_user_id uuid, p_plan jsonb, p_launch_status text DEFAULT NULL::text, p_lead_loop_verified boolean DEFAULT false, p_public_slug text DEFAULT NULL::text)
 RETURNS SETOF campaign_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  existing_campaign public.campaign_plans%rowtype;
  created_campaign public.campaign_plans%rowtype;
  campaign_count bigint := 0;
  billing_count bigint := 0;
  billing_plan_tier text := null;
  billing_status text := null;
  billing_period_end timestamptz := null;
  billing_cancel_at_period_end boolean := false;
  has_unlimited_campaigns boolean := false;
begin
  if p_campaign_id is null or p_organization_id is null or p_user_id is null then
    raise exception using
      errcode = '22023',
      message = 'campaign_creation_identity_required';
  end if;

  if p_plan is null or jsonb_typeof(p_plan) <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'campaign_creation_plan_required';
  end if;

  -- Serialize the count and insert decision per organization. This closes the
  -- two-request race that an application preflight followed by INSERT cannot.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_organization_id::text, 492724601)
  );

  -- Membership is authoritative on every invocation, including an exact
  -- idempotent replay. A removed member must not be able to use a previously
  -- created campaign id as a durable read capability.
  if not exists (
    select 1
    from public.organizations organization_record
    where organization_record.id = p_organization_id
      and organization_record.owner_user_id = p_user_id
  ) and not exists (
    select 1
    from public.organization_memberships membership_record
    where membership_record.organization_id = p_organization_id
      and membership_record.user_id = p_user_id
  ) then
    raise exception using
      errcode = '42501',
      message = 'campaign_creation_actor_not_member';
  end if;

  select candidate.*
  into existing_campaign
  from public.campaign_plans candidate
  where candidate.id = p_campaign_id;

  if found then
    if existing_campaign.organization_id is distinct from p_organization_id
       or existing_campaign.user_id is distinct from p_user_id then
      raise exception using
        errcode = '23505',
        message = 'campaign_creation_identity_collision';
    end if;

    -- Exact identity replay is intentionally read-only and does not consume a
    -- second entitlement slot or overwrite the original campaign document.
    return next existing_campaign;
    return;
  end if;

  select count(*)
  into billing_count
  from public.billing_subscriptions subscription_record
  where subscription_record.organization_id = p_organization_id;

  if billing_count > 1 then
    raise exception using
      errcode = 'P0001',
      message = 'campaign_creation_billing_ambiguous';
  end if;

  select
    lower(trim(subscription_record.plan_tier)),
    lower(trim(subscription_record.status)),
    subscription_record.current_period_end,
    subscription_record.cancel_at_period_end
  into
    billing_plan_tier,
    billing_status,
    billing_period_end,
    billing_cancel_at_period_end
  from public.billing_subscriptions subscription_record
  where subscription_record.organization_id = p_organization_id;

  has_unlimited_campaigns := coalesce(
    billing_plan_tier in ('pro', 'growth')
      and billing_status in ('active', 'trialing'),
    false
  );

  select count(*)
  into campaign_count
  from public.campaign_plans campaign_record
  where campaign_record.organization_id = p_organization_id;

  if not has_unlimited_campaigns and campaign_count >= 1 then
    raise exception using
      errcode = 'P0001',
      message = 'campaign_preview_limit_reached';
  end if;

  insert into public.campaign_plans (
    id,
    owner_id,
    organization_id,
    user_id,
    plan,
    launch_status,
    lead_loop_verified,
    public_slug
  ) values (
    p_campaign_id,
    p_organization_id::text,
    p_organization_id,
    p_user_id,
    p_plan,
    nullif(trim(p_launch_status), ''),
    coalesce(p_lead_loop_verified, false),
    nullif(trim(p_public_slug), '')
  )
  returning * into created_campaign;

  return next created_campaign;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_credit_top_up_intent_v1(p_intent_id uuid, p_organization_id uuid, p_user_id uuid, p_amount_cents integer, p_currency text, p_stripe_customer_id text)
 RETURNS SETOF credit_top_up_intents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  intent public.credit_top_up_intents%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception using errcode = '42501', message = 'credit_top_up_service_role_required';
  end if;

  if p_intent_id is null or p_organization_id is null or p_user_id is null
    or p_amount_cents is null or p_amount_cents < 2500 or p_amount_cents > 100000
    or lower(trim(coalesce(p_currency, ''))) <> 'usd'
    or nullif(trim(coalesce(p_stripe_customer_id, '')), '') is null then
    raise exception using errcode = '22023', message = 'credit_top_up_intent_invalid';
  end if;

  if not exists (
    select 1 from public.organizations organization_record
    where organization_record.id = p_organization_id
      and organization_record.owner_user_id = p_user_id
  ) and not exists (
    select 1 from public.organization_memberships membership_record
    where membership_record.organization_id = p_organization_id
      and membership_record.user_id = p_user_id
  ) then
    raise exception using errcode = '42501', message = 'credit_top_up_actor_not_member';
  end if;

  insert into public.credit_top_up_intents (
    id, organization_id, user_id, amount_cents, currency, stripe_customer_id
  ) values (
    p_intent_id,
    p_organization_id,
    p_user_id,
    p_amount_cents,
    lower(trim(p_currency)),
    trim(p_stripe_customer_id)
  )
  on conflict (id) do nothing;

  select * into strict intent
  from public.credit_top_up_intents existing
  where existing.id = p_intent_id;

  if intent.organization_id is distinct from p_organization_id
    or intent.user_id is distinct from p_user_id
    or intent.amount_cents is distinct from p_amount_cents
    or intent.currency is distinct from lower(trim(p_currency))
    or intent.stripe_customer_id is distinct from trim(p_stripe_customer_id) then
    raise exception using errcode = '23505', message = 'credit_top_up_intent_identity_collision';
  end if;

  return next intent;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ghl_hierarchy_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if (
    old.tenant_kind is distinct from new.tenant_kind
    or old.partner_id is distinct from new.partner_id
  ) and exists (
    select 1
    from public.ghl_location_mappings mapping_record
    where mapping_record.organization_id = old.organization_id
      and mapping_record.status in ('provisioning', 'active')
  ) then
    raise exception 'GHL workspace hierarchy cannot change while a routable location mapping exists.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ghl_installation_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if (
    old.environment is distinct from new.environment
    or old.owner_kind is distinct from new.owner_kind
    or old.partner_id is distinct from new.partner_id
    or old.provider_agency_id is distinct from new.provider_agency_id
  ) and exists (
    select 1
    from public.ghl_location_mappings mapping_record
    where mapping_record.installation_id = old.id
      and mapping_record.status in ('provisioning', 'active')
  ) then
    raise exception 'GHL installation identity cannot change while a routable location mapping exists.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ghl_lead_effect_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  transition_allowed boolean := false;
begin
  if tg_op = 'INSERT' then
    if new.status not in ('pending', 'operator_action_required') then
      raise exception 'A GHL lead effect must begin pending or explicitly operator-required.';
    end if;
    return new;
  end if;

  if old.organization_id is distinct from new.organization_id
     or old.lead_id is distinct from new.lead_id
     or old.location_mapping_id is distinct from new.location_mapping_id
     or old.effect_kind is distinct from new.effect_kind
     or old.idempotency_key is distinct from new.idempotency_key then
    raise exception 'GHL lead effect tenant and effect identity are immutable.';
  end if;

  if new.status = old.status then
    return new;
  end if;

  transition_allowed := case old.status
    when 'pending' then new.status in ('dispatching', 'canceled')
    when 'replay_requested' then new.status in ('dispatching', 'canceled')
    when 'dispatching' then new.status in ('uncertain', 'succeeded', 'retryable_failure', 'operator_action_required')
    when 'uncertain' then new.status in ('operator_action_required', 'canceled')
    when 'retryable_failure' then new.status in ('replay_requested', 'operator_action_required', 'canceled')
    when 'operator_action_required' then new.status in ('canceled')
    else false
  end;

  if not transition_allowed then
    raise exception 'Invalid GHL lead effect transition from % to %.', old.status, new.status;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ghl_location_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  tenant_record public.ghl_workspace_tenants%rowtype;
  installation_record public.ghl_installations%rowtype;
begin
  if tg_op = 'UPDATE' and (
    old.organization_id is distinct from new.organization_id
    or old.partner_id is distinct from new.partner_id
    or old.installation_id is distinct from new.installation_id
    or old.environment is distinct from new.environment
    or old.provider_location_id is distinct from new.provider_location_id
    or old.provisioning_owner is distinct from new.provisioning_owner
    or old.snapshot_manifest_id is distinct from new.snapshot_manifest_id
  ) then
    raise exception 'GHL mapping identity is immutable; retire it and create a reconciled replacement.';
  end if;

  select * into strict tenant_record
  from public.ghl_workspace_tenants
  where organization_id = new.organization_id;

  select * into strict installation_record
  from public.ghl_installations
  where id = new.installation_id
    and environment = new.environment;

  if tenant_record.tenant_kind = 'direct_realtor' and new.partner_id is not null then
    raise exception 'Direct realtor GHL mappings cannot carry a partner id.';
  end if;

  if tenant_record.tenant_kind = 'partner_child' and new.partner_id is distinct from tenant_record.partner_id then
    raise exception 'Partner-child GHL mapping does not match the workspace hierarchy.';
  end if;

  if installation_record.owner_kind = 'partner'
     and new.partner_id is distinct from installation_record.partner_id then
    raise exception 'Partner-owned GHL installation cannot be used outside its partner hierarchy.';
  end if;

  if new.provisioning_owner = 'partner' and new.partner_id is null then
    raise exception 'Partner provisioning requires a partner id.';
  end if;

  if tg_op = 'UPDATE'
     and old.status = 'active'
     and new.status <> 'active'
     and exists (
       select 1
       from public.ghl_provisioning_runs run_record
       where run_record.location_mapping_id = old.id
         and run_record.state = 'ready'
     ) then
    raise exception 'An active GHL mapping cannot be retired while a provisioning run is READY.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ghl_outbox_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  transition_allowed boolean := false;
begin
  if old.organization_id is distinct from new.organization_id
     or old.provisioning_run_id is distinct from new.provisioning_run_id
     or old.operation is distinct from new.operation
     or old.idempotency_key is distinct from new.idempotency_key
     or old.request_payload is distinct from new.request_payload then
    raise exception 'GHL provider outbox request identity is immutable.';
  end if;
  if new.attempt_count < old.attempt_count then
    raise exception 'GHL provider outbox attempt count cannot decrease.';
  end if;

  if new.status = 'dispatching' then
    if new.locked_at is null
       or new.locked_by is null
       or length(trim(new.locked_by)) = 0
       or new.lease_token is null
       or new.lease_expires_at is null
       or new.lease_expires_at <= new.locked_at then
      raise exception 'A dispatching GHL outbox row requires a complete live lease.';
    end if;

    if new.attempt_count <> old.attempt_count + 1
       or new.lease_generation <> old.lease_generation + 1 then
      raise exception 'Each GHL outbox claim must advance exactly one attempt and fencing generation.';
    end if;
  else
    if new.locked_at is not null
       or new.locked_by is not null
       or new.lease_token is not null
       or new.lease_expires_at is not null then
      raise exception 'A non-dispatching GHL outbox row cannot retain a worker lease.';
    end if;

    if new.attempt_count <> old.attempt_count
       or new.lease_generation <> old.lease_generation then
      raise exception 'GHL outbox attempts and fencing generations change only during claim.';
    end if;
  end if;

  if new.status = old.status then
    if new.status <> 'dispatching'
       and (
         new.locked_at is distinct from old.locked_at
         or new.locked_by is distinct from old.locked_by
         or new.lease_token is distinct from old.lease_token
         or new.lease_expires_at is distinct from old.lease_expires_at
       ) then
      raise exception 'GHL outbox lease fields cannot change outside a claim or settlement.';
    end if;
    return new;
  end if;

  transition_allowed := case old.status
    when 'pending' then new.status in ('dispatching', 'canceled')
    when 'retryable_failure' then new.status in ('pending', 'dispatching', 'operator_action_required', 'canceled')
    when 'dispatching' then new.status in (
      'pending',
      'uncertain',
      'succeeded',
      'retryable_failure',
      'operator_action_required',
      'canceled'
    )
    when 'uncertain' then new.status in ('dispatching', 'operator_action_required', 'canceled')
    when 'operator_action_required' then new.status = 'canceled'
    else false
  end;

  if not transition_allowed then
    raise exception 'Invalid GHL provider outbox transition from % to %.', old.status, new.status;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ghl_provisioning_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  mapping_record public.ghl_location_mappings%rowtype;
  manifest_record public.ghl_snapshot_manifests%rowtype;
  transition_allowed boolean := false;
begin
  if tg_op = 'INSERT' then
    if new.state <> 'requested' then
      raise exception 'A GHL provisioning run must begin in requested state.';
    end if;
    return new;
  end if;

  if old.organization_id is distinct from new.organization_id
     or old.environment is distinct from new.environment
     or old.activation_event_id is distinct from new.activation_event_id
     or old.installation_id is distinct from new.installation_id
     or old.snapshot_manifest_id is distinct from new.snapshot_manifest_id
     or old.idempotency_key is distinct from new.idempotency_key then
    raise exception 'GHL provisioning identity is immutable.';
  end if;

  if old.location_mapping_id is not null
     and old.location_mapping_id is distinct from new.location_mapping_id then
    raise exception 'An assigned GHL location mapping cannot be replaced in-place.';
  end if;

  if new.revision <> old.revision + 1 then
    raise exception 'GHL provisioning updates require exactly one optimistic revision increment.';
  end if;

  if new.state = old.state then
    if new.state = 'location_uncertain' and not new.reconcile_before_retry then
      raise exception 'An uncertain GHL location must retain its reconciliation gate.';
    end if;
    return new;
  end if;

  transition_allowed := case old.state
    when 'requested' then new.state in ('location_create_requested', 'operator_action_required', 'canceled')
    when 'location_create_requested' then new.state in ('location_uncertain', 'location_assigned', 'retryable_failure', 'operator_action_required', 'canceled')
    when 'location_uncertain' then new.state in ('location_assigned', 'retryable_failure', 'operator_action_required', 'canceled')
    when 'location_assigned' then new.state in ('snapshot_install_requested', 'operator_action_required', 'canceled')
    when 'snapshot_install_requested' then new.state in ('snapshot_installing', 'retryable_failure', 'operator_action_required', 'canceled')
    when 'snapshot_installing' then new.state in ('snapshot_verifying', 'retryable_failure', 'operator_action_required', 'canceled')
    when 'snapshot_verifying' then new.state in ('snapshot_installing', 'required_objects_verifying', 'retryable_failure', 'operator_action_required', 'canceled')
    when 'required_objects_verifying' then new.state in ('ready', 'retryable_failure', 'operator_action_required', 'canceled')
    when 'retryable_failure' then new.state in ('location_create_requested', 'snapshot_install_requested', 'snapshot_verifying', 'required_objects_verifying', 'operator_action_required', 'canceled')
    else false
  end;

  if not transition_allowed then
    raise exception 'Invalid GHL provisioning transition from % to %.', old.state, new.state;
  end if;

  if new.state = 'location_uncertain' then
    new.reconcile_before_retry = true;
  end if;

  if old.state = 'location_uncertain' and new.state = 'retryable_failure' then
    if new.last_reconciled_at is null or new.last_reconciled_at < old.updated_at then
      raise exception 'An uncertain GHL location result must be reconciled before retry.';
    end if;
    new.reconcile_before_retry = false;
  end if;

  if old.state = 'retryable_failure' then
    if old.resume_state is null or new.state <> old.resume_state then
      raise exception 'GHL replay must resume only the recorded retry state.';
    end if;
    new.resume_state = null;
    new.next_retry_at = null;
  end if;

  if new.state = 'ready' then
    if new.location_mapping_id is null then
      raise exception 'READY requires an active tenant/location mapping.';
    end if;

    select * into strict mapping_record
    from public.ghl_location_mappings
    where id = new.location_mapping_id
      and organization_id = new.organization_id
      and environment = new.environment
      and status = 'active';

    select * into strict manifest_record
    from public.ghl_snapshot_manifests
    where id = new.snapshot_manifest_id
      and environment = new.environment
      and status = 'approved';

    if mapping_record.snapshot_manifest_id is distinct from manifest_record.id
       or mapping_record.snapshot_verified_at is null
       or mapping_record.required_objects_verified_at is null then
      raise exception 'READY requires the approved snapshot and required-object verification.';
    end if;

    new.ready_at = coalesce(new.ready_at, timezone('utc', now()));
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ghl_snapshot_manifest_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if (
    old.environment is distinct from new.environment
    or old.snapshot_key is distinct from new.snapshot_key
    or old.snapshot_version is distinct from new.snapshot_version
    or old.provider_snapshot_id is distinct from new.provider_snapshot_id
    or old.required_objects is distinct from new.required_objects
  ) and exists (
    select 1
    from public.ghl_provisioning_runs run_record
    where run_record.snapshot_manifest_id = old.id
  ) then
    raise exception 'A referenced GHL snapshot manifest is immutable; create a new version.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_ghl_fake_lead_effects(p_organization_id uuid, p_lead_id uuid, p_environment text, p_now timestamp with time zone DEFAULT timezone('utc'::text, now()))
 RETURNS SETOF ghl_lead_effect_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  mapping_record public.ghl_location_mappings%rowtype;
  effect_kind_value text;
  operation_value text;
  outbox_key text;
  effect_key text;
  payload jsonb;
  outbox_record public.ghl_provider_outbox%rowtype;
  effect_record public.ghl_lead_effect_events%rowtype;
begin
  if p_environment <> 'test' then
    raise exception 'The GHL fake lead producer is restricted to the test environment.';
  end if;

  if not exists (
    select 1
    from public.leads
    where id = p_lead_id
      and organization_id = p_organization_id
  ) then
    raise exception 'GHL fake lead producer rejected a missing or cross-tenant lead.';
  end if;

  select * into mapping_record
  from public.ghl_location_mappings
  where organization_id = p_organization_id
    and environment = p_environment
    and status = 'active'
    and snapshot_verified_at is not null
    and required_objects_verified_at is not null
    and exists (
      select 1
      from public.ghl_workspace_tenants tenant
      where tenant.organization_id = p_organization_id
        and tenant.status = 'active'
    )
  order by updated_at desc
  limit 1;

  if not found then
    return;
  end if;

  foreach effect_kind_value in array array[
    'contact_upsert',
    'opportunity_upsert',
    'tag_apply',
    'workflow_enroll'
  ]
  loop
    operation_value := case effect_kind_value
      when 'contact_upsert' then 'lead_contact_upsert'
      when 'opportunity_upsert' then 'lead_opportunity_upsert'
      when 'tag_apply' then 'lead_tag_apply'
      when 'workflow_enroll' then 'lead_workflow_enroll'
    end;
    effect_key := concat(
      'ghl-fake-lead-effect-v1:',
      p_organization_id::text,
      ':',
      p_environment,
      ':',
      p_lead_id::text,
      ':',
      effect_kind_value
    );
    outbox_key := effect_key || ':outbox';
    payload := jsonb_build_object(
      'contract_version', 1,
      'fake_only', true,
      'organization_id', p_organization_id::text,
      'lead_id', p_lead_id::text,
      'location_mapping_id', mapping_record.id::text,
      'effect_kind', effect_kind_value
    );

    insert into public.ghl_provider_outbox (
      organization_id,
      provisioning_run_id,
      operation,
      idempotency_key,
      status,
      request_payload,
      available_at
    ) values (
      p_organization_id,
      null,
      operation_value,
      outbox_key,
      'pending',
      payload,
      p_now
    )
    on conflict (idempotency_key) do nothing
    returning * into outbox_record;

    if outbox_record.id is null then
      select * into strict outbox_record
      from public.ghl_provider_outbox
      where idempotency_key = outbox_key;

      if outbox_record.organization_id is distinct from p_organization_id
         or outbox_record.operation is distinct from operation_value
         or outbox_record.request_payload is distinct from payload then
        raise exception 'GHL fake lead outbox idempotency crossed an immutable boundary.';
      end if;
    end if;

    insert into public.ghl_lead_effect_events (
      organization_id,
      lead_id,
      location_mapping_id,
      effect_kind,
      idempotency_key,
      status,
      outbox_id,
      metadata
    ) values (
      p_organization_id,
      p_lead_id,
      mapping_record.id,
      effect_kind_value,
      effect_key,
      'pending',
      outbox_record.id,
      jsonb_build_object(
        'contract_version', 1,
        'fake_only', true,
        'provider_mutation_attempted', false
      )
    )
    on conflict (idempotency_key) do nothing
    returning * into effect_record;

    if effect_record.id is null then
      select * into strict effect_record
      from public.ghl_lead_effect_events
      where idempotency_key = effect_key;

      if effect_record.organization_id is distinct from p_organization_id
         or effect_record.lead_id is distinct from p_lead_id
         or effect_record.location_mapping_id is distinct from mapping_record.id
         or effect_record.effect_kind is distinct from effect_kind_value
         or effect_record.outbox_id is distinct from outbox_record.id then
        raise exception 'GHL fake lead effect idempotency crossed an immutable boundary.';
      end if;
    end if;

    return next effect_record;
    outbox_record := null;
    effect_record := null;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_user_credits(p_user_id uuid, p_organization_id uuid, p_amount integer, p_reason text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(balance integer, ledger_id uuid, reused_existing boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  balance_record public.organization_user_credits%rowtype;
  existing_ledger public.user_credit_ledger%rowtype;
  inserted_ledger public.user_credit_ledger%rowtype;
  normalized_reason text := nullif(trim(coalesce(p_reason, '')), '');
  normalized_reference_type text := nullif(trim(coalesce(p_reference_type, '')), '');
  normalized_reference_id text := nullif(trim(coalesce(p_reference_id, '')), '');
  normalized_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  next_balance integer;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception using errcode = '42501', message = 'credit_service_role_required';
  end if;

  if p_user_id is null or p_organization_id is null
    or p_amount is null or p_amount <= 0
    or normalized_reason is null then
    raise exception using errcode = '22023', message = 'credit_grant_identity_invalid';
  end if;

  if not exists (
    select 1 from public.organizations organization_record
    where organization_record.id = p_organization_id
      and organization_record.owner_user_id = p_user_id
  ) and not exists (
    select 1 from public.organization_memberships membership_record
    where membership_record.organization_id = p_organization_id
      and membership_record.user_id = p_user_id
  ) then
    raise exception using errcode = '42501', message = 'credit_actor_not_workspace_member';
  end if;

  insert into public.organization_user_credits (organization_id, user_id, balance)
  values (p_organization_id, p_user_id, 0)
  on conflict (organization_id, user_id) do nothing;

  select * into strict balance_record
  from public.organization_user_credits credit_record
  where credit_record.organization_id = p_organization_id
    and credit_record.user_id = p_user_id
  for update;

  if normalized_idempotency_key is not null then
    select * into existing_ledger
    from public.user_credit_ledger ledger_record
    where ledger_record.organization_id = p_organization_id
      and ledger_record.user_id = p_user_id
      and ledger_record.idempotency_key = normalized_idempotency_key
    limit 1;

    if existing_ledger.id is not null then
      if existing_ledger.delta is distinct from p_amount
        or existing_ledger.reason is distinct from normalized_reason
        or existing_ledger.reference_type is distinct from normalized_reference_type
        or existing_ledger.reference_id is distinct from normalized_reference_id then
        raise exception using errcode = '23505', message = 'credit_idempotency_identity_collision';
      end if;

      return query select existing_ledger.balance_after, existing_ledger.id, true;
      return;
    end if;
  end if;

  next_balance := balance_record.balance + p_amount;

  update public.organization_user_credits credit_record
  set balance = next_balance,
      updated_at = timezone('utc', now())
  where credit_record.organization_id = p_organization_id
    and credit_record.user_id = p_user_id;

  insert into public.user_credit_ledger (
    user_id,
    organization_id,
    delta,
    balance_after,
    reason,
    reference_type,
    reference_id,
    idempotency_key,
    metadata
  ) values (
    p_user_id,
    p_organization_id,
    p_amount,
    next_balance,
    normalized_reason,
    normalized_reference_type,
    normalized_reference_id,
    normalized_idempotency_key,
    coalesce(p_metadata, '{}'::jsonb)
  ) returning * into inserted_ledger;

  return query select next_balance, inserted_ledger.id, false;
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_stripe_webhook_processing_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.status = 'processing' then
    if tg_op = 'INSERT' or old.status <> 'processing' then
      new.processing_claim_token := coalesce(new.processing_claim_token, gen_random_uuid());
      new.processing_claim_generation := greatest(
        coalesce(new.processing_claim_generation, 0),
        case when tg_op = 'UPDATE' then coalesce(old.processing_claim_generation, 0) + 1 else 1 end
      );
      new.processing_locked_until := coalesce(
        new.processing_locked_until,
        timezone('utc', now()) + interval '5 minutes'
      );
    else
      new.processing_claim_token := coalesce(new.processing_claim_token, old.processing_claim_token);
      new.processing_claim_generation := greatest(
        coalesce(new.processing_claim_generation, 0),
        coalesce(old.processing_claim_generation, 1)
      );
      new.processing_locked_until := coalesce(
        new.processing_locked_until,
        old.processing_locked_until,
        timezone('utc', now()) + interval '5 minutes'
      );
    end if;
  else
    new.processing_claim_token := null;
    new.processing_locked_until := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.persist_campaign_launch_runtime_claim(p_launch_id uuid, p_worker_id text, p_lease_token uuid, p_lease_generation bigint, p_launch_runtime jsonb, p_message text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  launch public.campaign_launch_records%rowtype;
  campaign public.campaign_plans%rowtype;
  launch_state text;
  runtime_status text;
  runtime_patch jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role is required to persist launch runtime';
  end if;

  if jsonb_typeof(coalesce(p_launch_runtime, 'null'::jsonb)) <> 'object'
    or octet_length(p_launch_runtime::text) > 16384
    or nullif(trim(coalesce(p_message, '')), '') is null
    or length(p_message) > 1000 then
    raise exception 'campaign launch runtime payload is invalid';
  end if;

  launch_state := p_launch_runtime ->> 'status';
  if launch_state not in ('pending', 'in_progress', 'failed') then
    raise exception 'terminal launch runtime must be persisted by the completion RPC';
  end if;

  select * into launch
  from public.campaign_launch_records candidate
  where candidate.id = p_launch_id
  for update;

  if launch.id is null
    or launch.result_status <> 'processing'
    or launch.schedule_locked_by is distinct from p_worker_id
    or launch.schedule_lease_token is distinct from p_lease_token
    or launch.schedule_lease_generation is distinct from p_lease_generation
    or launch.schedule_locked_until <= timezone('utc', now()) then
    return false;
  end if;

  select * into campaign
  from public.campaign_plans candidate
  where candidate.id = launch.campaign_id
    and candidate.organization_id = launch.organization_id
    and candidate.user_id = launch.user_id
  for update;

  if campaign.id is null then
    raise exception 'campaign launch runtime target does not match its tenant';
  end if;

  runtime_status := case
    when launch_state = 'failed' then 'launch_ready'
    else 'launching'
  end;
  runtime_patch := jsonb_build_object(
    'campaignId', p_launch_runtime -> 'campaign_id',
    'adSetId', p_launch_runtime -> 'adset_id',
    'creativeId', p_launch_runtime -> 'creative_id',
    'adId', p_launch_runtime -> 'ad_id',
    'metaAdSetIds', case
      when nullif(trim(coalesce(p_launch_runtime ->> 'adset_id', '')), '') is null
        then '[]'::jsonb
      else jsonb_build_array(p_launch_runtime ->> 'adset_id')
    end,
    'metaCreativeIds', case
      when nullif(trim(coalesce(p_launch_runtime ->> 'creative_id', '')), '') is null
        then '[]'::jsonb
      else jsonb_build_array(p_launch_runtime ->> 'creative_id')
    end,
    'metaAdIds', case
      when nullif(trim(coalesce(p_launch_runtime ->> 'ad_id', '')), '') is null
        then '[]'::jsonb
      else jsonb_build_array(p_launch_runtime ->> 'ad_id')
    end,
    'metaPushStatus', case when launch_state = 'failed' then 'failed' else 'publishing' end,
    'status', runtime_status,
    'metaLastMessage', trim(p_message),
    'lastAction', trim(p_message),
    'statusUpdatedAt', coalesce(p_launch_runtime -> 'updated_at', to_jsonb(timezone('utc', now())))
  );

  update public.campaign_plans candidate
  set plan = jsonb_set(
        jsonb_set(
          coalesce(candidate.plan, '{}'::jsonb),
          '{launch_runtime}',
          p_launch_runtime,
          true
        ),
        '{runtime}',
        coalesce(candidate.plan -> 'runtime', '{}'::jsonb) || runtime_patch,
        true
      ),
      launch_status = runtime_status,
      updated_at = timezone('utc', now())
  where candidate.id = campaign.id
    and candidate.organization_id = launch.organization_id
    and candidate.user_id = launch.user_id;

  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_commercial_activation_with_initial_credit(p_organization_id uuid, p_user_id uuid, p_source_event_id text, p_source_event_type text, p_source_event_created bigint, p_source_payment_id text, p_source_subscription_id text, p_amount_paid_cents integer, p_currency text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(activation_id uuid, activation_created boolean, initial_credit_granted boolean, balance integer, ledger_id uuid, reused_existing boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  activation_row public.commercial_activations%rowtype;
  credit_balance integer;
  credit_ledger_id uuid;
  credit_reused boolean;
begin
  if p_organization_id is null or p_user_id is null then
    raise exception 'organization_id and user_id are required';
  end if;

  if not exists (
    select 1
      from public.organizations organization_record
     where organization_record.id = p_organization_id
       and organization_record.owner_user_id = p_user_id
  ) and not exists (
    select 1
      from public.organization_memberships membership_record
     where membership_record.organization_id = p_organization_id
       and membership_record.user_id = p_user_id
  ) then
    raise exception 'commercial activation user is not a member of the organization';
  end if;

  if p_source_event_id is null or length(trim(p_source_event_id)) = 0 then
    raise exception 'source_event_id is required';
  end if;

  if p_source_event_type not in ('checkout.session.completed', 'invoice.payment_succeeded') then
    raise exception 'source_event_type is not a qualifying payment event';
  end if;

  if p_amount_paid_cents is null or p_amount_paid_cents <= 0 then
    raise exception 'amount_paid_cents must be positive';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text, 0));

  select *
    into activation_row
    from public.commercial_activations
   where organization_id = p_organization_id
   limit 1;

  if found then
    select ledger.balance_after, ledger.id
      into credit_balance, credit_ledger_id
      from public.user_credit_ledger ledger
     where ledger.reference_type = 'commercial_activation'
       and ledger.reference_id = activation_row.id::text
       and ledger.idempotency_key = 'commercial_activation_initial_credit:' || p_organization_id::text
     limit 1;

    if credit_ledger_id is null then
      raise exception 'commercial activation exists without its initial credit ledger entry';
    end if;

    return query
      select activation_row.id, false, false, credit_balance, credit_ledger_id, true;
    return;
  end if;

  insert into public.commercial_activations (
    organization_id,
    user_id,
    source_event_id,
    source_event_type,
    source_event_created,
    source_payment_id,
    source_subscription_id,
    amount_paid_cents,
    currency,
    metadata
  )
  values (
    p_organization_id,
    p_user_id,
    trim(p_source_event_id),
    p_source_event_type,
    greatest(coalesce(p_source_event_created, 0), 0),
    nullif(trim(coalesce(p_source_payment_id, '')), ''),
    nullif(trim(coalesce(p_source_subscription_id, '')), ''),
    p_amount_paid_cents,
    nullif(lower(trim(coalesce(p_currency, ''))), ''),
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning * into activation_row;

  select grant_result.balance, grant_result.ledger_id, grant_result.reused_existing
    into credit_balance, credit_ledger_id, credit_reused
    from public.grant_user_credits(
      p_user_id,
      p_organization_id,
      1000,
      'commercial_activation_initial_credit',
      'commercial_activation',
      activation_row.id::text,
      'commercial_activation_initial_credit:' || p_organization_id::text,
      jsonb_build_object(
        'activationId', activation_row.id,
        'sourceEventId', activation_row.source_event_id,
        'sourceEventType', activation_row.source_event_type
      )
    ) grant_result;

  if credit_ledger_id is null or credit_reused then
    raise exception 'initial commercial activation credit was not created atomically';
  end if;

  return query
    select activation_row.id, true, true, credit_balance, credit_ledger_id, false;
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_provider_usage(p_organization_id uuid, p_user_id uuid, p_campaign_id uuid, p_provider text, p_operation text, p_limit_count integer, p_idempotency_key text DEFAULT NULL::text, p_estimated_cost numeric DEFAULT NULL::numeric)
 RETURNS TABLE(allowed boolean, current_count integer, next_count integer, limit_count integer, usage_id uuid, event_id uuid, reused_existing boolean, event_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  today date := current_date;
  usage_row public.provider_usage_limits%rowtype;
  existing_event public.provider_usage_events%rowtype;
  new_event public.provider_usage_events%rowtype;
begin
  if p_user_id is null then
    raise exception 'p_user_id is required';
  end if;

  if p_limit_count <= 0 then
    raise exception 'p_limit_count must be positive';
  end if;

  if p_idempotency_key is not null then
    select *
    into existing_event
    from public.provider_usage_events
    where idempotency_key = p_idempotency_key
      and organization_id = p_organization_id
      and user_id = p_user_id
      and coalesce(campaign_id, '00000000-0000-0000-0000-000000000000'::uuid) =
          coalesce(p_campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)
      and provider = p_provider
      and operation = p_operation
      and usage_date = today
    limit 1;

    if existing_event.id is not null then
      select *
      into usage_row
      from public.provider_usage_limits
      where user_id = existing_event.user_id
        and coalesce(campaign_id, '00000000-0000-0000-0000-000000000000'::uuid) =
            coalesce(existing_event.campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)
        and provider = existing_event.provider
        and operation = existing_event.operation
        and usage_date = existing_event.usage_date;

      allowed := true;
      current_count := greatest(coalesce(usage_row.usage_count, 1) - 1, 0);
      next_count := coalesce(usage_row.usage_count, 1);
      limit_count := coalesce(usage_row.limit_count, p_limit_count);
      usage_id := usage_row.id;
      event_id := existing_event.id;
      reused_existing := true;
      event_status := existing_event.status;
      return next;
      return;
    end if;
  end if;

  begin
    insert into public.provider_usage_limits (
      organization_id,
      user_id,
      campaign_id,
      provider,
      operation,
      usage_date,
      usage_count,
      limit_count
    )
    values (
      p_organization_id,
      p_user_id,
      p_campaign_id,
      p_provider,
      p_operation,
      today,
      0,
      p_limit_count
    );
  exception when unique_violation then
    update public.provider_usage_limits
    set limit_count = p_limit_count,
        updated_at = now()
    where user_id = p_user_id
      and coalesce(campaign_id, '00000000-0000-0000-0000-000000000000'::uuid) =
          coalesce(p_campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)
      and provider = p_provider
      and operation = p_operation
      and usage_date = today;
  end;

  select *
  into usage_row
  from public.provider_usage_limits
  where user_id = p_user_id
    and coalesce(campaign_id, '00000000-0000-0000-0000-000000000000'::uuid) =
        coalesce(p_campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)
    and provider = p_provider
    and operation = p_operation
    and usage_date = today
  for update;

  if usage_row.usage_count >= p_limit_count then
    allowed := false;
    current_count := usage_row.usage_count;
    next_count := usage_row.usage_count;
    limit_count := p_limit_count;
    usage_id := usage_row.id;
    event_id := null;
    reused_existing := false;
    event_status := null;
    return next;
    return;
  end if;

  update public.provider_usage_limits
  set usage_count = usage_row.usage_count + 1,
      limit_count = p_limit_count,
      updated_at = now()
  where id = usage_row.id;

  insert into public.provider_usage_events (
    organization_id,
    user_id,
    campaign_id,
    provider,
    operation,
    idempotency_key,
    usage_date,
    estimated_cost,
    status
  )
  values (
    p_organization_id,
    p_user_id,
    p_campaign_id,
    p_provider,
    p_operation,
    nullif(trim(coalesce(p_idempotency_key, '')), ''),
    today,
    p_estimated_cost,
    'reserved'
  )
  returning * into new_event;

  allowed := true;
  current_count := usage_row.usage_count;
  next_count := usage_row.usage_count + 1;
  limit_count := p_limit_count;
  usage_id := usage_row.id;
  event_id := new_event.id;
  reused_existing := false;
  event_status := new_event.status;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_provider_usage_attempt_v2(p_organization_id uuid, p_user_id uuid, p_campaign_id uuid, p_provider text, p_operation text, p_limit_count integer, p_idempotency_key text, p_attempt_key text, p_settlement_token uuid, p_estimated_cost numeric DEFAULT NULL::numeric, p_credit_amount integer DEFAULT 0, p_credit_reason text DEFAULT 'provider_generation'::text)
 RETURNS TABLE(allowed boolean, block_reason text, current_count integer, next_count integer, limit_count integer, usage_id uuid, event_id uuid, reused_existing boolean, event_status text, settlement_token uuid, settlement_generation bigint, credit_balance integer, credit_ledger_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  today date := current_date;
  usage_record public.provider_usage_limits%rowtype;
  existing_event public.provider_usage_events%rowtype;
  inserted_event public.provider_usage_events%rowtype;
  balance_record public.organization_user_credits%rowtype;
  debit_ledger public.user_credit_ledger%rowtype;
  normalized_provider text := nullif(trim(coalesce(p_provider, '')), '');
  normalized_operation text := nullif(trim(coalesce(p_operation, '')), '');
  normalized_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  normalized_attempt_key text := nullif(trim(coalesce(p_attempt_key, '')), '');
  normalized_credit_reason text := nullif(trim(coalesce(p_credit_reason, '')), '');
begin
  if auth.role() is distinct from 'service_role' then
    raise exception using errcode = '42501', message = 'provider_usage_service_role_required';
  end if;

  if p_organization_id is null or p_user_id is null
    or normalized_provider is null or normalized_operation is null
    or normalized_idempotency_key is null or normalized_attempt_key is null
    or p_settlement_token is null
    or p_limit_count is null or p_limit_count <= 0
    or p_credit_amount is null or p_credit_amount < 0
    or normalized_credit_reason is null then
    raise exception using errcode = '22023', message = 'provider_usage_attempt_identity_invalid';
  end if;

  if not exists (
    select 1 from public.organizations organization_record
    where organization_record.id = p_organization_id
      and organization_record.owner_user_id = p_user_id
  ) and not exists (
    select 1 from public.organization_memberships membership_record
    where membership_record.organization_id = p_organization_id
      and membership_record.user_id = p_user_id
  ) then
    raise exception using errcode = '42501', message = 'provider_usage_actor_not_workspace_member';
  end if;

  if p_campaign_id is not null and not exists (
    select 1 from public.campaign_plans campaign_record
    where campaign_record.id = p_campaign_id
      and campaign_record.organization_id = p_organization_id
      and campaign_record.user_id = p_user_id
  ) then
    raise exception using errcode = '42501', message = 'provider_usage_campaign_scope_mismatch';
  end if;

  begin
    insert into public.provider_usage_limits (
      organization_id,
      user_id,
      campaign_id,
      provider,
      operation,
      usage_date,
      usage_count,
      limit_count
    ) values (
      p_organization_id,
      p_user_id,
      p_campaign_id,
      normalized_provider,
      normalized_operation,
      today,
      0,
      p_limit_count
    );
  exception when unique_violation then
    null;
  end;

  select * into strict usage_record
  from public.provider_usage_limits usage_limit
  where usage_limit.organization_id = p_organization_id
    and usage_limit.user_id = p_user_id
    and coalesce(usage_limit.campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)
      = coalesce(p_campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)
    and usage_limit.provider = normalized_provider
    and usage_limit.operation = normalized_operation
    and usage_limit.usage_date = today
  for update;

  select * into existing_event
  from public.provider_usage_events event_record
  where event_record.organization_id = p_organization_id
    and event_record.user_id = p_user_id
    and (
      event_record.idempotency_key = normalized_idempotency_key
      or event_record.attempt_key = normalized_attempt_key
    )
  order by event_record.created_at asc
  limit 1;

  if existing_event.id is not null then
    if existing_event.organization_id is distinct from p_organization_id
      or existing_event.user_id is distinct from p_user_id
      or existing_event.campaign_id is distinct from p_campaign_id
      or existing_event.provider is distinct from normalized_provider
      or existing_event.operation is distinct from normalized_operation
      or existing_event.idempotency_key is distinct from normalized_idempotency_key
      or existing_event.attempt_key is distinct from normalized_attempt_key then
      raise exception using errcode = '23505', message = 'provider_usage_attempt_identity_collision';
    end if;

    allowed := false;
    block_reason := case
      when existing_event.status = 'reserved' then 'attempt_in_progress'
      when existing_event.status = 'consumed' then 'attempt_consumed'
      when existing_event.status = 'operator_action_required' then 'operator_action_required'
      else 'attempt_terminal'
    end;
    current_count := greatest(usage_record.usage_count - 1, 0);
    next_count := usage_record.usage_count;
    limit_count := usage_record.limit_count;
    usage_id := usage_record.id;
    event_id := existing_event.id;
    reused_existing := true;
    event_status := existing_event.status;
    settlement_token := existing_event.settlement_token;
    settlement_generation := existing_event.settlement_generation;
    credit_ledger_id := existing_event.credit_ledger_id;
    if existing_event.compensation_ledger_id is not null then
      select ledger_record.balance_after into credit_balance
      from public.user_credit_ledger ledger_record
      where ledger_record.id = existing_event.compensation_ledger_id;
    elsif existing_event.credit_ledger_id is not null then
      select ledger_record.balance_after into credit_balance
      from public.user_credit_ledger ledger_record
      where ledger_record.id = existing_event.credit_ledger_id;
    end if;
    return next;
    return;
  end if;

  if usage_record.usage_count >= p_limit_count then
    return query select
      false,
      'limit_reached'::text,
      usage_record.usage_count,
      usage_record.usage_count,
      p_limit_count,
      usage_record.id,
      null::uuid,
      false,
      null::text,
      null::uuid,
      null::bigint,
      null::integer,
      null::uuid;
    return;
  end if;

  insert into public.organization_user_credits (organization_id, user_id, balance)
  values (p_organization_id, p_user_id, 0)
  on conflict (organization_id, user_id) do nothing;

  select * into strict balance_record
  from public.organization_user_credits credit_record
  where credit_record.organization_id = p_organization_id
    and credit_record.user_id = p_user_id
  for update;

  if balance_record.balance < p_credit_amount then
    return query select
      false,
      'credit_insufficient'::text,
      usage_record.usage_count,
      usage_record.usage_count,
      p_limit_count,
      usage_record.id,
      null::uuid,
      false,
      null::text,
      null::uuid,
      null::bigint,
      balance_record.balance,
      null::uuid;
    return;
  end if;

  insert into public.provider_usage_events (
    organization_id,
    user_id,
    campaign_id,
    provider,
    operation,
    idempotency_key,
    attempt_key,
    settlement_token,
    settlement_generation,
    usage_date,
    estimated_cost,
    status,
    metadata
  ) values (
    p_organization_id,
    p_user_id,
    p_campaign_id,
    normalized_provider,
    normalized_operation,
    normalized_idempotency_key,
    normalized_attempt_key,
    p_settlement_token,
    1,
    today,
    p_estimated_cost,
    'reserved',
    jsonb_build_object('attemptKey', normalized_attempt_key)
  ) returning * into inserted_event;

  if p_credit_amount > 0 then
    credit_balance := balance_record.balance - p_credit_amount;

    update public.organization_user_credits credit_record
    set balance = credit_balance,
        updated_at = timezone('utc', now())
    where credit_record.organization_id = p_organization_id
      and credit_record.user_id = p_user_id;

    insert into public.user_credit_ledger (
      user_id,
      organization_id,
      delta,
      balance_after,
      reason,
      reference_type,
      reference_id,
      idempotency_key,
      metadata
    ) values (
      p_user_id,
      p_organization_id,
      -p_credit_amount,
      credit_balance,
      normalized_credit_reason,
      'provider_usage_event',
      inserted_event.id::text,
      'provider_usage_debit:' || inserted_event.id::text,
      jsonb_build_object(
        'provider', normalized_provider,
        'operation', normalized_operation,
        'attemptKey', normalized_attempt_key
      )
    ) returning * into debit_ledger;

    update public.provider_usage_events event_record
    set credit_ledger_id = debit_ledger.id
    where event_record.id = inserted_event.id;
  else
    credit_balance := balance_record.balance;
  end if;

  update public.provider_usage_limits usage_limit
  set usage_count = usage_record.usage_count + 1,
      limit_count = p_limit_count,
      updated_at = timezone('utc', now())
  where usage_limit.id = usage_record.id;

  allowed := true;
  block_reason := null;
  current_count := usage_record.usage_count;
  next_count := usage_record.usage_count + 1;
  limit_count := p_limit_count;
  usage_id := usage_record.id;
  event_id := inserted_event.id;
  reused_existing := false;
  event_status := 'reserved';
  settlement_token := p_settlement_token;
  settlement_generation := 1;
  credit_ledger_id := debit_ledger.id;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_ghl_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$function$
